${pagingBottom}

SELECT

FROM
	CHECKINOUT
WHERE
	homepage_id = #{homepage_id}
AND checkInOut_idx = #{checkInOut_idx}

SELECT RESULT_DATE, SUM(RESULT_COUNT) AS RESULT_COUNT FROM ( SELECT TO_CHAR(checkIn_time, 'YYYY-MM-DD') AS result_date , '1' AS result_count FROM CHECKINOUT WHERE homepage_id = #{homepage_id}
AND TO_CHAR(checkIn_time,'yyyy-MM-dd') BETWEEN #{start_date} AND #{end_date}
GROUP BY (TO_CHAR(checkIn_time, 'YYYY-MM-DD'), member_id) ) GROUP BY result_date ORDER BY result_date ASC

